const projectId = $('GET timeline').first().json.params?.id;
const auth      = $input.first().json;
const query     = $('GET timeline').first().json.query || {};

if (!projectId || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(projectId)) {
  return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project id (UUID) requerido' } }];
}

const limit = Math.min(parseInt(query.limit || '50'), 500);
let cursorBefore = null;
if (query.cursor) {
  try { cursorBefore = JSON.parse(Buffer.from(query.cursor, 'base64url').toString('utf8')); } catch {}
}

return [{ json: {
  user_id:    auth.user_id,
  tenant_id:  auth.tenant_id,
  role:       auth.role,
  project_id: projectId,
  limit,
  cursor_before: cursorBefore,
  request_id: 'req_' + Math.random().toString(36).slice(2, 10)
}}];

const items   = $input.all().map(i => i.json);
const params  = $('Validate Params').first().json;
const limit   = params.limit;

const hasMore = items.length > limit;
const page    = hasMore ? items.slice(0, limit) : items;

let cursorNext = null;
if (hasMore && page.length > 0) {
  const last = page[page.length - 1];
  cursorNext = Buffer.from(JSON.stringify({ id: last.id, ts: last.timestamp })).toString('base64url');
}

return [{ json: {
  data: page.map(t => ({
    id:             t.id,
    timestamp:      t.timestamp,
    agent_name:     t.agent_name,
    action:         t.action,
    status:         t.status,
    output_summary: t.output_summary,
    details:        t.details || {}
  })),
  meta: {
    request_id: params.request_id,
    timestamp:  new Date().toISOString(),
    pagination: {
      cursor_next:     cursorNext,
      cursor_prev:     null,
      has_more:        hasMore,
      total_estimated: page.length + (hasMore ? 1 : 0)
    }
  }
}}];
